// Pretend every check just ran and found nothing, so WordPress never contacts api.wordpress.org.
function perfectpixel_disable_updates_core() {
	return (object) array(
		'last_checked'    => time(),
		'version_checked' => get_bloginfo( 'version' ),
		'updates'         => array(),
		'translations'    => array(),
	);
}

function perfectpixel_disable_updates_list() {
	return (object) array(
		'last_checked' => time(),
		'checked'      => array(),
		'response'     => array(),
		'no_update'    => array(),
		'translations' => array(),
	);
}

function perfectpixel_disable_updates_checks() {
	remove_action( 'admin_init', '_maybe_update_core' );
	remove_action( 'admin_init', '_maybe_update_plugins' );
	remove_action( 'admin_init', '_maybe_update_themes' );
	remove_action( 'wp_version_check', 'wp_version_check' );
	remove_action( 'wp_update_plugins', 'wp_update_plugins' );
	remove_action( 'wp_update_themes', 'wp_update_themes' );
	remove_action( 'wp_maybe_auto_update', 'wp_maybe_auto_update' );
	remove_action( 'init', 'wp_schedule_update_checks' );
}

function perfectpixel_disable_updates_menu() {
	remove_submenu_page( 'index.php', 'update-core.php' );
}
